args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeLabel ?country ?countryLabel WHERE {
  VALUES ?place { dbr:Mavrolithari dbr:Ampelakia,_Evros }
  OPTIONAL { ?place dbo:country ?country1 . }
  OPTIONAL { ?place dbp:country ?country2 . }
  BIND(COALESCE(?country1, ?country2) AS ?country)
  OPTIONAL { ?place rdfs:label ?placeLabel . FILTER(lang(?placeLabel) = "en") }
  OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = "en") }
}

